@ vpy_update_buttons() — cache buttons (+axes if analog is used)
.global vpy_update_buttons
.type vpy_update_buttons, %function
.thumb_func
vpy_update_buttons:
    push    {r4, lr}
    svc     #14                     @ SYS_READ_BUTTONS_RAW
    mov     r4, r0
    ubfx    r0, r4, #8, #8
    ldr     r1, =BTN_STATE_J1
    str     r0, [r1]
    and     r0, r4, #0xFF
    ldr     r1, =BTN_STATE_J2
    str     r0, [r1]
    svc     #13                     @ SYS_READ_AXES (analog used)
    mov     r4, r0
    ubfx    r0, r4, #24, #8
    sxtb    r0, r0
    ldr     r1, =J1_AXIS_X
    str     r0, [r1]
    ubfx    r0, r4, #16, #8
    sxtb    r0, r0
    ldr     r1, =J1_AXIS_Y
    str     r0, [r1]
    ubfx    r0, r4, #8, #8
    sxtb    r0, r0
    ldr     r1, =J2_AXIS_X
    str     r0, [r1]
    sxtb    r0, r4
    ldr     r1, =J2_AXIS_Y
    str     r0, [r1]
    pop     {r4, pc}
    .ltorg

@ psg_write(r0=reg, r1=data) — BIOS trap: SYS_PSG_WRITE
.global psg_write
.type psg_write, %function
.thumb_func
psg_write:
    svc     #5                      @ SYS_PSG_WRITE
    bx      lr

@ psg_read(r0=reg) -> r0=data — BIOS trap: SYS_PSG_READ
.global psg_read
.type psg_read, %function
.thumb_func
psg_read:
    svc     #12                     @ SYS_PSG_READ
    bx      lr

.global vpy_abs
.type vpy_abs, %function
.thumb_func
vpy_abs:
    cmp     r0, #0
    it      lt
    neglt   r0, r0
    bx      lr

.global vpy_min
.type vpy_min, %function
.thumb_func
vpy_min:
    cmp     r0, r1
    it      gt
    movgt   r0, r1
    bx      lr

.global vpy_max
.type vpy_max, %function
.thumb_func
vpy_max:
    cmp     r0, r1
    it      lt
    movlt   r0, r1
    bx      lr

.global vpy_clamp
.type vpy_clamp, %function
.thumb_func
vpy_clamp:
    cmp     r0, r1
    it      lt
    movlt   r0, r1
    cmp     r0, r2
    it      gt
    movgt   r0, r2
    bx      lr

@ vpy_play_music(r0=music_data_ptr) — BIOS trap: SYS_PLAY_MUSIC
.global vpy_play_music
.type vpy_play_music, %function
.thumb_func
vpy_play_music:
    svc     #21                     @ SYS_PLAY_MUSIC
    bx      lr

@ vpy_stop_music() — BIOS trap: SYS_STOP_MUSIC
.global vpy_stop_music
.type vpy_stop_music, %function
.thumb_func
vpy_stop_music:
    svc     #22                     @ SYS_STOP_MUSIC
    bx      lr

