@ vpy_load_level(r0=level_data_ptr)
.global vpy_load_level
.type vpy_load_level, %function
.thumb_func
vpy_load_level:
    push    {r4, r5, r6, r7, r8, lr}  @ 6 regs = 24 bytes, 8-aligned
    mov     r4, r0
    ldr     r1, =LEVEL_DATA_PTR
    str     r0, [r1]
    ldrb    r5, [r4, #9]              @ gpCount
    ldr     r1, =LEVEL_GP_COUNT
    str     r5, [r1]
    cmp     r5, #0
    beq.w   vll_done
    ldr     r6, [r4, #16]             @ gpObjectsPtr
    ldr     r7, =LEVEL_GP_BUF
vll_gp_loop:
    ldrsh   r0, [r6, #0]              @ world_x
    ldrsh   r1, [r6, #2]              @ world_y
    strh    r0, [r7, #0]
    strh    r1, [r7, #2]
    ldrsb   r0, [r6, #14]             @ vel_x_init
    ldrsb   r1, [r6, #15]             @ vel_y_init
    strb    r0, [r7, #4]
    strb    r1, [r7, #5]
    mov     r0, #1
    strb    r0, [r7, #6]  @ alive=1
    mov     r0, #0
    strb    r0, [r7, #7]  @ pad=0
    add     r6, r6, #20    @ next ROM obj (20 bytes)
    add     r7, r7, #8
    subs    r5, r5, #1
    bne     vll_gp_loop
vll_done:
    ldrsh   r0, [r4, #24]             @ scrollLimit left
    ldr     r1, =SCROLL_LIMIT_LEFT
    str     r0, [r1]
    ldrsh   r0, [r4, #26]             @ scrollLimit right
    ldr     r1, =SCROLL_LIMIT_RIGHT
    str     r0, [r1]
    ldrsh   r0, [r4, #28]             @ scrollLimit top
    ldr     r1, =SCROLL_LIMIT_TOP
    str     r0, [r1]
    ldrsh   r0, [r4, #30]             @ scrollLimit bottom
    ldr     r1, =SCROLL_LIMIT_BOTTOM
    str     r0, [r1]
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ vpy_show_level()
.global vpy_show_level
.type vpy_show_level, %function
.thumb_func
vpy_show_level:
    push    {r4, r5, r6, r7, r8, lr}  @ 6 regs = 24 bytes, 8-aligned
    ldr     r4, =LEVEL_DATA_PTR
    ldr     r4, [r4]
    cmp     r4, #0
    beq.w   vsl_done
    ldrb    r5, [r4, #8]              @ bgCount
    cmp     r5, #0
    beq.w   vsl_skip_bg
    ldr     r6, [r4, #12]             @ bgObjectsPtr
    bl      vsl_draw_static
vsl_skip_bg:
    ldr     r5, =LEVEL_GP_COUNT
    ldr     r5, [r5]
    cmp     r5, #0
    beq.w   vsl_skip_gp
    ldr     r6, [r4, #16]             @ gpObjectsPtr (ROM)
    ldr     r7, =LEVEL_GP_BUF
    ldr     r8, =CAMERA_X
vsl_gp_loop:
    ldrb    r3, [r6, #7]              @ obj type (1=enemy)
    cmp     r3, #1
    beq     vsl_gp_next               @ enemies drawn by DRAW_ENEMIES
    ldrb    r0, [r7, #6]              @ alive
    cmp     r0, #0
    beq.w   vsl_gp_next
    ldrsh   r0, [r7, #0]              @ world_x
    ldrsh   r1, [r7, #2]              @ world_y
    ldr     r2, [r8]
    sub     r0, r0, r2  @ screen_x
    ldr     r2, [r8, #4]
    sub     r1, r1, r2  @ screen_y (CAMERA_Y=CAMERA_X+4)
    movs    r2, r0
    bpl     vsl_gp_cx_ok
    neg     r2, r0
vsl_gp_cx_ok:
    cmp     r2, #160
    bgt     vsl_gp_next
    movs    r2, r1
    bpl     vsl_gp_cy_ok
    neg     r2, r1
vsl_gp_cy_ok:
    cmp     r2, #160
    bgt     vsl_gp_next
    ldrb    r2, [r6, #5]              @ intensity
    cmp     r2, #0
    bne     vsl_gp_havei
    mov     r2, #127
vsl_gp_havei:
    mov     r3, #0
    push    {r2, r3}            @ [sp]=intensity, align+8
    mov     r2, r1
    mov     r1, r0
    ldr     r0, [r6, #8]  @ vector_ptr
    mov     r3, #0
    bl      vpy_draw_vector_ex
    add     sp, sp, #8
vsl_gp_next:
    add     r6, r6, #20    @ next ROM obj (20 bytes)
    add     r7, r7, #8
    subs    r5, r5, #1
    bne     vsl_gp_loop
vsl_skip_gp:
    ldrb    r5, [r4, #10]             @ fgCount
    cmp     r5, #0
    beq.w   vsl_done
    ldr     r6, [r4, #20]             @ fgObjectsPtr
    bl      vsl_draw_static
vsl_done:
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ vsl_draw_static — internal
vsl_draw_static:
    push    {r4, r5, r6, r7, r8, lr}  @ 24 bytes
    mov     r4, r5                    @ count
    mov     r5, r6                    @ ROM ptr
    ldr     r6, =CAMERA_X
    ldr     r6, [r6]
    ldr     r7, =CAMERA_Y
    ldr     r7, [r7]
vsd_loop:
    cmp     r4, #0
    beq.w   vsd_done
    ldrsh   r0, [r5, #0]
    ldrsh   r1, [r5, #2]
    sub     r0, r0, r6
    sub     r1, r1, r7
    movs    r8, r0
    bpl     vsd_cx_ok
    neg     r8, r0
vsd_cx_ok:
    cmp     r8, #160
    bgt     vsd_next
    movs    r8, r1
    bpl     vsd_cy_ok
    neg     r8, r1
vsd_cy_ok:
    cmp     r8, #160
    bgt     vsd_next
    ldrb    r2, [r5, #5]
    cmp     r2, #0
    bne     vsd_havei
    mov     r2, #127
vsd_havei:
    mov     r3, #0
    push    {r2, r3}
    mov     r2, r1
    mov     r1, r0
    ldr     r0, [r5, #8]
    mov     r3, #0
    bl      vpy_draw_vector_ex
    add     sp, sp, #8
vsd_next:
    add     r5, r5, #20    @ next ROM obj (20 bytes)
    subs    r4, r4, #1
    b       vsd_loop
vsd_done:
    pop     {r4, r5, r6, r7, r8, pc}
    .ltorg

@ vpy_update_level()
.global vpy_update_level
.type vpy_update_level, %function
.thumb_func
vpy_update_level:
    push    {r4, r5, r6, r7, r8, r9, r10, lr}  @ 8 regs = 32 bytes, 8-aligned
    ldr     r4, =LEVEL_DATA_PTR
    ldr     r4, [r4]
    cmp     r4, #0
    beq.w   vul_done
    ldrsh   r6, [r4, #0]              @ xMin
    ldrsh   r7, [r4, #2]              @ xMax
    ldrsh   r8, [r4, #4]              @ yMin
    ldrsh   r9, [r4, #6]              @ yMax
    ldr     r5, =LEVEL_GP_COUNT
    ldr     r5, [r5]
    cmp     r5, #0
    beq.w   vul_done
    ldr     r10, [r4, #16]            @ gpObjectsPtr (ROM, for flags)
    ldr     r4, =LEVEL_GP_BUF
vul_loop:
    ldrb    r0, [r4, #6]              @ alive
    cmp     r0, #0
    beq.w   vul_next
    ldrb    r0, [r10, #6]             @ ROM flags
    tst     r0, #0x02
    beq     vul_nograv
    ldrsb   r1, [r4, #5]              @ vel_y
    sub     r1, r1, #1
    cmp     r1, #-127
    bge     vul_vy_ok
    mov     r1, #-127
vul_vy_ok:
    strb    r1, [r4, #5]
vul_nograv:
    ldrsh   r1, [r4, #0]              @ world_x
    ldrsb   r2, [r4, #4]              @ vel_x
    add     r1, r1, r2
    cmp     r1, r6
    bge     vul_x_min_ok
    mov     r1, r6
    mov     r2, #0
    strb    r2, [r4, #4]
vul_x_min_ok:
    cmp     r1, r7
    ble     vul_x_max_ok
    mov     r1, r7
    mov     r2, #0
    strb    r2, [r4, #4]
vul_x_max_ok:
    strh    r1, [r4, #0]
    ldrsh   r1, [r4, #2]              @ world_y
    ldrsb   r2, [r4, #5]              @ vel_y
    add     r1, r1, r2
    cmp     r1, r8
    bge     vul_y_min_ok
    mov     r1, r8
    mov     r2, #0
    strb    r2, [r4, #5]
vul_y_min_ok:
    cmp     r1, r9
    ble     vul_y_max_ok
    mov     r1, r9
    mov     r2, #0
    strb    r2, [r4, #5]
vul_y_max_ok:
    strh    r1, [r4, #2]
vul_next:
    add     r4, r4, #8
    add     r10, r10, #20  @ next ROM obj (20 bytes)
    subs    r5, r5, #1
    bne     vul_loop
vul_done:
    pop     {r4, r5, r6, r7, r8, r9, r10, pc}
    .ltorg

@ vpy_get_level_width() -> r0
