@ vpy_get_level_tile(r0=x, r1=y) -> index or -1
.global vpy_get_level_tile
.type vpy_get_level_tile, %function
.thumb_func
vpy_get_level_tile:
    push    {r4, r5, r6, lr}           @ 4 regs = 16 bytes, 8-aligned
    mov     r4, r0                    @ query_x
    mov     r5, r1                    @ query_y
    ldr     r6, =LEVEL_GP_COUNT
    ldr     r6, [r6]
    ldr     r0, =LEVEL_GP_BUF
    mov     r1, #0                    @ index
vglt_loop:
    cmp     r1, r6
    bge     vglt_notfound
    ldrb    r2, [r0, #6]
    cmp     r2, #0
    beq.w   vglt_next
    ldrsh   r2, [r0, #0]              @ world_x
    sub     r2, r2, r4
    movs    r3, r2
    bpl     vglt_dx_ok
    neg     r2, r2
vglt_dx_ok:
    cmp     r2, #16
    bgt     vglt_next
    ldrsh   r2, [r0, #2]              @ world_y
    sub     r2, r2, r5
    movs    r3, r2
    bpl     vglt_dy_ok
    neg     r2, r2
vglt_dy_ok:
    cmp     r2, #16
    bgt     vglt_next
    mov     r0, r1                    @ return index
    pop     {r4, r5, r6, pc}
vglt_next:
    add     r0, r0, #8
    add     r1, r1, #1
    b       vglt_loop
vglt_notfound:
    mvn     r0, #0            @ return -1
    pop     {r4, r5, r6, pc}
    .ltorg

