@ vpy_print_msg(r0=id): renders message at pre-defined (x,y)
.global vpy_print_msg
.type vpy_print_msg, %function
.thumb_func
vpy_print_msg:
    push    {r4, lr}              @ 2 regs = 8 bytes, 8-aligned
    cmp     r0, #0
    beq.w   vpm_done
    sub     r0, r0, #1            @ 0-based index
    lsl     r4, r0, #3            @ byte offset = index * 8
    ldr     r0, =PRINT_MSG_TABLE
    add     r4, r4, r0            @ entry ptr
    ldrsb   r0, [r4, #0]          @ x
    ldrsb   r1, [r4, #1]          @ y
    ldr     r2, [r4, #4]          @ str_ptr
    bl      vpy_print_text
vpm_done:
    pop     {r4, pc}
    .ltorg

