@ --- wall_compartment (4 path(s)) ---
.global _WALL_COMPARTMENT_VECTORS
_WALL_COMPARTMENT_VECTORS:
    .word   4               @ path_count
    .word   _WALL_COMPARTMENT_PATH0      @ ptr path 0
    .word   _WALL_COMPARTMENT_PATH1      @ ptr path 1
